// Dynamic fields (2026-10-13, Graham meeting) — every piece of text or media on a page that comes
// from data rather than being fixed copy, where that data comes from, and what to show when it's
// missing. The Page Debugger (page-debugger.js → "Dynamic fields") outlines each one on the page
// and shows this entry on hover; it is also the field list for Marc.
//
// Fields
//   id      dotted key, grouped by area (header.*, pdp.*, plp.*, …) — never rename once shared
//   label   what it is, in plain words
//   source  a key of RRG_DYN_SOURCES
//   token   what "Show field names" writes in place of the value: the element's text with each
//           dynamic part as {entity.attribute_code}, e.g. 'Shop {category.name} for your
//           {vehicle.make} {vehicle.model}'. Real Magento attribute codes where they exist.
//           When `sel` matches different kinds of element, an object instead:
//           { 'selector': 'template', '*': 'template for the rest' } (first match wins).
//   attr    the field / attribute it reads ("Rackit: Important Vehicle Fit Notes", "Magento: price")
//   sel     CSS selector(s) of the element(s) on the page that show it
//   pages   template folders it applies to (omit = every page the selector matches on)
//   rule    the fallback chain, in order: what to use first, then the fallback, then hide/empty
//   example a real value as it comes out of the source (when it differs from what's displayed)
//   notes   anything else Marc needs
//   status  'draft' (Claude's best guess, not yet checked) | 'confirmed' (Brenton has checked it)

const RRG_DYN_SOURCES = {
  rackit:  { label: 'Rackit', desc: 'Product + fitment data from Rackit (vehicle fit, USPs, fit notes, fitment gallery)' },
  magento: { label: 'Magento', desc: 'Catalogue + store data in Magento (name, price, stock, images, categories, cart)' },
  reviews: { label: 'REVIEWS.io', desc: 'Ratings and reviews from the REVIEWS.io API' },
  session: { label: 'Shopper session', desc: "This shopper's own state: saved vehicle, nearest store, login, cart, recent searches" },
  cms:     { label: 'CMS / config', desc: 'Set by the team in Magento admin: CMS blocks, banners, sale campaigns, region config' },
  algolia: { label: 'Algolia', desc: 'Search: the Algolia indices behind the header typeahead and Search Results (products, pages, articles, brands, facets)' },
  calc:    { label: 'Calculated', desc: 'Worked out on the page from other fields (savings, counts, totals, dates)' },
  unknown: { label: 'Unknown', desc: 'Source not known yet: needs an answer from Marc / the Rackit owner' },
};

